def _resolve_workplan_groups(plan) -> tuple[list[WorkGroup], bool]:
    """Extract workplan groups from plan (or strategy.parallelisable_workplan)."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    groups = getattr(workplan, 'groups', []) if workplan else []
    return groups, bool(workplan)


def _check_group_tasks(group: WorkGroup, seen: set[str], violations: list[str]) -> None:
    """Check file-path invariants for all tasks in a group."""
    tasks = getattr(group, 'tasks', []) or []
    for task in tasks:
        _check_task_invariants(task, seen, violations)


def _check_task_invariants(task, seen: set[str], violations: list[str]) -> None:
    """Check that a task has exactly 1 file path and no collisions."""
    fps = getattr(task, 'file_paths', None) or []
    if len(fps) != 1:
        violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")
    for fp in fps:
        if fp in seen:
            violations.append(f'file collision: {fp} in multiple tasks')
        seen.add(fp)"}
